#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int ans = 0;
    for (int i = 0; i < 100000000; i += 25) {
        string test = std::to_string(i);
        if (test.length() != s.length()) continue;

        int xValue = -1;
        bool works = true;

        for (size_t j = 0; j < s.length(); j++) {
            if (s[j] == 'X') {
                if (xValue == -1) {
                    xValue = test[j];
                }
                if (test[j] != xValue) {
                    works = false;
                    break;
                }
            } else if (s[j] != '_') {
                if (test[j] != s[j]) {
                    works = false;
                    break;
                }
            }
        }

        if (works) ans++;
    }
    cout << ans << "\n";

    return 0;
}
